inline const uint8_t* getRetroScreenAsset(int gameIndex, size_t &outSize) {
    switch (gameIndex) {
        case 0: outSize = RETRO_ASSET_CONTRA_SIZE; return retro_asset_contra;
        case 1: outSize = RETRO_ASSET_POKEMON_SIZE; return retro_asset_pokemon;
        case 2: outSize = RETRO_ASSET_RADRACER_SIZE; return retro_asset_radracer;
        default: outSize = RETRO_ASSET_RADRACER_SIZE; return retro_asset_radracer;
    }
}

